import React from 'react';

export function Tabs({ tabs, active }: { tabs: string[]; active?: string }) {
  const [current, setCurrent] = React.useState(active ?? tabs[0]);
  return (
    <div role="tablist" aria-label="Tabs" style={{ display: 'flex', gap: '4px', borderBottom: '1px solid {{token:colors.base.border}}' }}>
      {tabs.map((t) => (
        <button key={t} role="tab" aria-selected={t === current} onClick={() => setCurrent(t)}
          style={{
            padding: '{{token:spacing.sidebar.padding}}',
            border: 'none',
            background: 'transparent',
            color: t === current ? '{{token:colors.accent.primary}}' : '{{token:colors.text.secondary}}',
            borderBottom: t === current ? '2px solid {{token:colors.accent.primary}}' : '2px solid transparent',
            fontWeight: t === current ? 600 : 400,
            cursor: 'pointer',
            fontSize: '{{token:typography.scale.sm}}',
          }}>
          {t}
        </button>
      ))}
    </div>
  );
}
